{"file_path":"src/scanner.js","content":"/**
 * Scanner for the little language.
 *
 * Works on an array of code points so that astral characters count as one
 * column and are reported whole.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isDigit = (c) => c !== null && c >= '0' && c <= '9'
const isHex = (c) => c !== null && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOctal = (c) => c !== null && c >= '0' && c <= '7'
const isAlpha = (c) => c !== null && /^[a-zA-Z_]$/.test(c)
const isAlnum = (c) => c !== null && /^[a-zA-Z0-9_]$/.test(c)

class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    return idx < this.chars.length ? this.chars[idx] : null
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  advance() {
    if (this.atEnd()) return null
    const c = this.chars[this.pos]
    if (c === '\n') {
      this.line++
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }
    this.pos++
    return c
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  push(line, column, kind, body) {
    this.tokens.push({ line, column, kind, body })
  }

  // --- comments -----------------------------------------------------------

  skipLineComment() {
    this.advance()
    this.advance()
    while (!this.atEnd() && this.peek() !== '\n') this.advance()
  }

  skipBlockComment() {
    const line = this.line
    const column = this.column
    this.advance()
    this.advance()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) this.fail(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  // --- words --------------------------------------------------------------

  scanWord() {
    const line = this.line
    const column = this.column
    let text = ''
    while (isAlnum(this.peek())) text += this.advance()
    this.push(line, column, KEYWORDS.has(text) ? 'keyword' : 'ident', text)
  }

  // --- numbers ------------------------------------------------------------

  numberError(start, line, column) {
    // Everything the scanner ran through, trailing characters included.
    while (isAlnum(this.peek())) this.advance()
    const text = this.chars.slice(start, this.pos).join('')
    this.fail(line, column, `invalid number ${text}`)
  }

  /**
   * Reads a run of digits accepted by `ok`, where an underscore is only valid
   * between two such digits. Returns false when the run held no digit or when
   * an underscore sat somewhere it may not.
   */
  scanDigitRun(ok) {
    let digits = 0
    for (;;) {
      const c = this.peek()
      if (c !== null && ok(c)) {
        digits++
        this.advance()
      } else if (c === '_') {
        if (digits === 0) return false
        const next = this.peek(1)
        if (next === null || !ok(next)) return false
        this.advance()
      } else {
        return digits > 0
      }
    }
  }

  scanNumber() {
    const line = this.line
    const column = this.column
    const start = this.pos

    const first = this.peek()
    const second = this.peek(1)

    if (first === '0' && (second === 'x' || second === 'X')) {
      this.advance()
      this.advance()
      if (!this.scanDigitRun(isHex)) this.numberError(start, line, column)
    } else if (first === '0' && (second === 'b' || second === 'B')) {
      this.advance()
      this.advance()
      if (!this.scanDigitRun(isBin)) this.numberError(start, line, column)
    } else if (first === '0' && (second === 'o' || second === 'O')) {
      this.advance()
      this.advance()
      if (!this.scanDigitRun(isOctal)) this.numberError(start, line, column)
    } else {
      if (!this.scanDigitRun(isDigit)) this.numberError(start, line, column)

      if (this.peek() === '.' && isDigit(this.peek(1))) {
        this.advance()
        if (!this.scanDigitRun(isDigit)) this.numberError(start, line, column)
      }

      const marker = this.peek()
      if (marker === 'e' || marker === 'E') {
        const next = this.peek(1)
        const signed = next === '+' || next === '-'
        if (isDigit(next) || (signed && isDigit(this.peek(2)))) {
          this.advance()
          if (signed) this.advance()
          if (!this.scanDigitRun(isDigit)) this.numberError(start, line, column)
        }
      }
    }

    if (isAlnum(this.peek())) this.numberError(start, line, column)

    this.push(line, column, 'number', this.chars.slice(start, this.pos).join(''))
  }

  // --- strings ------------------------------------------------------------

  scanEscape() {
    // Positioned on the backslash.
    const line = this.line
    const column = this.column
    this.advance()

    const c = this.peek()
    if (c === null) this.fail(line, column, 'invalid escape \\')

    switch (c) {
      case 'n':
        this.advance()
        return '\n'
      case 't':
        this.advance()
        return '\t'
      case 'r':
        this.advance()
        return '\r'
      case '\\':
        this.advance()
        return '\\'
      case '"':
        this.advance()
        return '"'
      case '0':
        this.advance()
        return '\0'
      case 'x': {
        this.advance()
        const a = this.peek()
        if (!isHex(a)) this.fail(line, column, 'invalid escape \\x')
        this.advance()
        const b = this.peek()
        if (!isHex(b)) this.fail(line, column, 'invalid escape \\x')
        this.advance()
        return String.fromCharCode(parseInt(a + b, 16))
      }
      case 'u': {
        this.advance()
        if (this.peek() !== '{') this.fail(line, column, 'invalid escape \\u')
        this.advance()
        let hex = ''
        while (isHex(this.peek())) hex += this.advance()
        if (hex.length === 0 || this.peek() !== '}') this.fail(line, column, 'invalid escape \\u')
        const value = parseInt(hex, 16)
        if (!(value <= 0x10ffff)) this.fail(line, column, 'invalid escape \\u')
        this.advance()
        return String.fromCodePoint(value)
      }
      default:
        this.fail(line, column, `invalid escape \\${c}`)
        return ''
    }
  }

  scanString() {
    const line = this.line
    const column = this.column
    this.advance()

    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') this.fail(this.line, this.column, 'newline in string')
      if (c === '\\') {
        value += this.scanEscape()
      } else {
        value += this.advance()
      }
    }

    this.push(line, column, 'string', JSON.stringify(value))
  }

  scanRawString() {
    const line = this.line
    const column = this.column
    this.advance() // r
    this.advance() // "

    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      const c = this.advance()
      if (c === '"') break
      value += c
    }

    this.push(line, column, 'rawstring', JSON.stringify(value))
  }

  // --- driver -------------------------------------------------------------

  scan() {
    while (!this.atEnd()) {
      const c = this.peek()

      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }

      if (c === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }

      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }

      if (c === 'r' && this.peek(1) === '"') {
        this.scanRawString()
        continue
      }

      if (isAlpha(c)) {
        this.scanWord()
        continue
      }

      if (isDigit(c)) {
        this.scanNumber()
        continue
      }

      if (c === '"') {
        this.scanString()
        continue
      }

      const pair = c + (this.peek(1) ?? '')
      if (PUNCT2.includes(pair)) {
        const line = this.line
        const column = this.column
        this.advance()
        this.advance()
        this.push(line, column, 'punct', pair)
        continue
      }

      if (PUNCT1.includes(c)) {
        const line = this.line
        const column = this.column
        this.advance()
        this.push(line, column, 'punct', c)
        continue
      }

      this.fail(this.line, this.column, `unexpected character ${c}`)
    }

    return this.tokens
  }
}

/**
 * Scans the source, returning either its tokens or the first error.
 */
export function scan(source) {
  const scanner = new Scanner(source)
  try {
    return { tokens: scanner.scan(), error: null }
  } catch (err) {
    if (err instanceof ScanError) {
      return { tokens: null, error: { line: err.line, column: err.column, reason: err.reason } }
    }
    throw err
  }
}
