/**
 * Scanner for the programming language.
 * Tokenizes source code into positioned tokens.
 */

export class Scanner {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.error = null;
  }

  peek(offset = 0) {
    const idx = this.pos + offset;
    return idx < this.source.length ? this.source[idx] : null;
  }

  advance() {
    if (this.pos >= this.source.length) return;

    const char = this.source[this.pos];
    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else if (char === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5;
    } else {
      this.column++;
    }
    this.pos++;
  }

  setError(line, column, message) {
    if (!this.error) {
      this.error = { line, column, message };
    }
  }

  skipWhitespace() {
    while (this.peek() && /[ \t\r\n]/.test(this.peek())) {
      this.advance();
    }
  }

  skipLineComment() {
    // Skip '//'
    this.advance();
    this.advance();
    // Skip until '\n' or end
    while (this.peek() && this.peek() !== '\n') {
      this.advance();
    }
  }

  skipBlockComment() {
    const startLine = this.line;
    const startCol = this.column;
    // Skip '/*'
    this.advance();
    this.advance();

    let depth = 1;
    while (depth > 0 && this.peek()) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance();
        this.advance();
        depth++;
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance();
        this.advance();
        depth--;
      } else {
        this.advance();
      }
    }

    if (depth > 0) {
      this.setError(startLine, startCol, 'unterminated block comment');
    }
  }

  scanIdentifierOrKeyword() {
    const startLine = this.line;
    const startCol = this.column;
    let value = '';

    while (this.peek() && /[a-zA-Z_0-9]/.test(this.peek())) {
      value += this.peek();
      this.advance();
    }

    const keywords = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null']);
    const kind = keywords.has(value) ? 'keyword' : 'ident';

    this.tokens.push({
      line: startLine,
      column: startCol,
      kind,
      body: value,
    });
  }

  scanNumber() {
    const startLine = this.line;
    const startCol = this.column;
    let value = '';

    // Check for prefix (0x, 0b, 0o)
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      value += this.peek();
      this.advance();
      value += this.peek();
      this.advance();

