      let hasDigits = false;

      // Scan hex digits with optional underscores
      while (this.peek() && /[0-9a-fA-F_]/.test(this.peek())) {
        if (this.peek() !== '_') {
          hasDigits = true;
        }
        value += this.peek();
        this.advance();
      }

      if (!hasDigits) {
        // No hex digits after 0x - error
        this.setError(startLine, startCol, `invalid number ${value}`);
        return;
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      value += this.peek();
      this.advance();
      value += this.peek();
      this.advance();

      let hasDigits = false;

      // Scan binary digits with optional underscores
      while (this.peek() && /[01_]/.test(this.peek())) {
