        switch (char) {
          case 'n':
            decoded += '\n';
            this.advance();
            break;
          case 't':
            decoded += '\t';
            this.advance();
            break;
          case 'r':
            decoded += '\r';
            this.advance();
            break;
          case '\\':
            decoded += '\\';
            this.advance();
            break;
          case '"':
            decoded += '"';
            this.advance();
            break;
          case '0':
            decoded += '\0';
            this.advance();
            break;
          case 'x': {
            this.advance();
            const hex1 = this.peek();
            if (!hex1 || !/[0-9a-fA-F]/.test(hex1)) {
              this.setError(this.line, backslashCol, `invalid escape \\x`);
              return;
            }
            this.advance();
            const hex2 = this.peek();
            if (!hex2 || !/[0-9a-fA-F]/.test(hex2)) {
              this.setError(this.line, backslashCol, `invalid escape \\x`);
              return;
            }
            const code = parseInt(`${hex1}${hex2}`, 16);
            decoded += String.fromCharCode(code);
            this.advance();
            break;
          }
          case 'u': {
            this.advance();
            if (this.peek() !== '{') {
              this.setError(this.line, backslashCol, `invalid escape \\u`);
              return;
            }
            this.advance();
            let hex = '';
            while (this.peek() && /[0-9a-fA-F]/.test(this.peek())) {
              hex += this.peek();
              this.advance();
            }
            if (!hex || this.peek() !== '}') {
              this.setError(this.line, backslashCol, `invalid escape \\u`);
              return;
            }
            const codePoint = parseInt(hex, 16);
            if (codePoint > 0x10ffff) {
              this.setError(this.line, backslashCol, `invalid escape \\u`);
              return;
            }
            decoded += String.fromCodePoint(codePoint);
            this.advance(); // skip }
            break;
          }
          default:
            this.setError(this.line, backslashCol, `invalid escape \\${char}`);
            return;
        }
      } else {
        decoded += this.peek();
        this.advance();
      }
    }

    if (!this.peek()) {
      this.setError(startLine, startCol, 'unterminated string');
      return;
    }

    // Skip closing quote
    this.advance();

    this.tokens.push({
      line: startLine,
      column: startCol,
      kind: 'string',
      body: JSON.stringify(decoded),
    });
  }

  scanRawString() {
    const startLine = this.line;
    const startCol = this.column;
    // Skip 'r'
    this.advance();
    // Skip opening quote
    this.advance();

    let content = '';
    while (this.peek() && this.peek() !== '"') {
      content += this.peek();
      this.advance();
    }

    if (!this.peek()) {
      this.setError(startLine, startCol, 'unterminated string');
      return;
    }

    // Skip closing quote
    this.advance();

    this.tokens.push({
      line: startLine,
      column: startCol,
      kind: 'rawstring',
      body: JSON.stringify(content),
    });
  }

  scanPunctuation() {
    const startLine = this.line;
    const startCol = this.column;

    const twoChar = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>'];

    const char = this.peek();
    const char2 = char + (this.peek(1) || '');

    if (twoChar.includes(char2)) {
      this.advance();
      this.advance();
      this.tokens.push({
        line: startLine,
        column: startCol,
        kind: 'punct',
        body: char2,
      });
      return;
    }

    const oneChar = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'];

    if (oneChar.includes(char)) {
      this.advance();
      this.tokens.push({
        line: startLine,
        column: startCol,
        kind: 'punct',
        body: char,
      });
      return;
    }

    // Should not reach here
    this.advance();
  }

  scan() {
    while (this.pos < this.source.length && !this.error) {
      this.skipWhitespace();
      if (this.pos >= this.source.length || this.error) break;

      // Check for comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment();
        continue;
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment();
        if (this.error) break;
        continue;
      }

      // Check for tokens
      const char = this.peek();

      if (char === 'r' && this.peek(1) === '"') {
        this.scanRawString();
        if (this.error) break;
      } else if (/[a-zA-Z_]/.test(char)) {
        this.scanIdentifierOrKeyword();
      } else if (/[0-9]/.test(char)) {
        this.scanNumber();
        if (this.error) break;
      } else if (char === '"') {
        this.scanString();
        if (this.error) break;
      } else if (char === 'r' && this.peek(1) === '"') {
        this.scanRawString();
        if (this.error) break;
      } else if (['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'].includes(char)) {
        this.scanPunctuation();
      } else {
        // Unexpected character
        const line = this.line;
        const col = this.column;
        this.setError(line, col, `unexpected character ${char}`);
        break;
      }
    }

    return {
      tokens: this.tokens,
      error: this.error,
    };
  }
}

