{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usage() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function render(mode, tokens) {
  if (mode === 'tokens') {
    return tokens.map((t) => `${t.line}:${t.column} ${t.kind} ${t.body}\n`).join('')
  }

  const counts = new Map(KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)

  let out = ''
  for (const kind of KINDS) out += `${kind} ${counts.get(kind)}\n`
  out += `total ${tokens.length}\n`
  return out
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'tokens' && argv[0] !== 'stats')) usage()
  const mode = argv[0]

  const chunks = []
  process.stdin.on('data', (chunk) => chunks.push(chunk))
  process.stdin.on('end', () => {
    const source = Buffer.concat(chunks).toString('utf8')
    const { tokens, error } = scan(source)

    if (error) {
      process.stderr.write(`error: ${error.line}:${error.column}: ${error.reason}\n`)
      process.exitCode = 2
      return
    }

    process.stdout.write(render(mode, tokens))
    process.exitCode = 0
  })
}

main()
"}

