import { Scanner } from './scanner.js';

const mode = process.argv[2];

if (!mode || (mode !== 'tokens' && mode !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n');
  process.exit(2);
}

let input = '';
process.stdin.setEncoding('utf8');

process.stdin.on('data', (chunk) => {
  input += chunk;
});

process.stdin.on('end', () => {
  const scanner = new Scanner(input);
  const { tokens, error } = scanner.scan();

  if (error) {
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.message}\n`);
    process.exit(2);
  }

  if (mode === 'tokens') {
    for (const token of tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`);
    }
  } else if (mode === 'stats') {
    const stats = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    };

    for (const token of tokens) {
      stats[token.kind]++;
    }

    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${stats[kind]}\n`);
    }

    const total = tokens.length;
    process.stdout.write(`total ${total}\n`);
  }

  process.exit(0);
});

